const booksTitle='owner form create, Add with all fields, publication, repeat edits and archive reload';
const booksSnapshot=(patch={})=>({version:1,stage:'setup',ownerState:'unavailable',button:'unavailable',route:'unavailable',sample:'unavailable',...patch});
const booksMarker=s=>`[books-diagnostic-v1:${Object.keys(booksEnums).map(k=>s[k]).join('|')}]`;
const booksFixture=()=>{const lane=manifest().lanes.find(l=>l.name==='books'),identity=lane.identities.find(i=>i.project==='books-desktop'&&i.titlePath.at(-1)===booksTitle),index=lane.identities.indexOf(identity),report=rawReport(lane,true),c=child(lane);assert.ok(identity);c.status=1;c.receipt.results[index].status='unexpected';c.receipt.results[index].attempts[0].status='failed';const result=report.suites[0].specs[index].tests[0].results[0]={status:'failed',retry:0,errors:[{message:booksMarker(booksSnapshot())}]};return {lane,identity,index,report,c,result,failure:{version:1,lane:lane.name,provenance,results:c.receipt.results,child:{status:1,signal:null},cleanup:{status:'passed'},artifacts:c.receipt.artifacts}};};
const booksMetadata=f=>decodeProtectedFailureDiagnostics(f.report,f.lane,process.cwd()).filter(d=>Object.hasOwn(d,'books'));
const booksValidate=(f,s,patch={})=>validateFailureRecord(f.lane,{...f.failure,diagnostics:[{identity:f.identity,kind:'error',matcher:'unknown',locations:[],books:s,...patch}]},provenance,f.c);
test('Books bounded diagnostic: every coherent enum roundtrips and validates independently',()=>{for(const [key,values]of Object.entries(booksEnums))for(const value of values){const s=booksSnapshot({[key]:value,...(key==='sample'?{}:key==='stage'?{}:{sample:'captured'})}),f=booksFixture();f.result.errors[0].message=booksMarker(s);assert.equal(booksMetadata(f).length,1);assert.deepEqual(booksMetadata(f)[0].books,s);assert.doesNotThrow(()=>booksValidate(f,s));}});
