test('Profile bounded diagnostic: frozen six titles tuples aggregate all original bodies calls and protected contracts',async()=>{const {ts,source}=await profileAST(),normalized=profileWithoutSecondSave(ts,source).replace(/\/\/ BEGIN PROFILE ONBOARDING DIAGNOSTIC[\s\S]*?\/\/ END PROFILE ONBOARDING DIAGNOSTIC\s*/, '').replace(/try \{\s*(await expect\(page\.getByRole\('textbox', \{ name: 'Enter your mobile number' \}\)\)\.toBeVisible\(\);)\s*\} catch \(error\) \{\s*await captureProfileOnboarding\(page, test\.info\(\)\);\s*throw error;\s*\}/,'$1'),sf=ts.createSourceFile('profile.ts',normalized,ts.ScriptTarget.Latest,true,ts.ScriptKind.TS),printer=ts.createPrinter({removeComments:true}),print=n=>printer.printNode(ts.EmitHint.Unspecified,n,sf),tests=profileTests(ts,sf);assert.equal(tests.length,6);assert.deepEqual(tests.map(c=>c.arguments[0].text),profileFrozenInventory.map(i=>i.title));for(let i=0;i<tests.length;i++){const body=tests[i].arguments[0].text===profileTitle?profileNativeBusinessBody(ts,sf,tests[i].arguments[1].body):tests[i].arguments[1].body,calls=[];function visit(n){if(ts.isCallExpression(n)&&n.expression.getText(sf)!=='setProfileDiagnosticState')calls.push(print(n));ts.forEachChild(n,visit);}visit(body);assert.deepEqual(calls,profileFrozenInventory[i].calls,'original calls and arguments in order: '+i);if(tests[i].arguments[0].text!==profileTitle)assert.equal(print(body),profileFrozenInventory[i].body,'other original body: '+i);else {function strip(n){if(ts.isBlock(n))return ts.factory.updateBlock(n,n.statements.filter(s=>!profileWrite(ts,sf,s)).map(strip));if(ts.isForOfStatement(n)){const statement=strip(n.statement);if(ts.isBlock(statement)&&n.expression.getText(sf)==="['books', 'movies', 'games'] as const"&&statement.statements.length===1&&statement.statements[0].getText(sf).includes('await createNavigationList(page, category)'))return ts.factory.updateForOfStatement(n,n.awaitModifier,n.initializer,n.expression,statement.statements[0]);return ts.factory.updateForOfStatement(n,n.awaitModifier,n.initializer,n.expression,statement);}return n;}assert.equal(print(strip(body)),profileFrozenInventory[i].body,'only synchronous setters and specific creation block permitted');}}for(const frozen of profileFrozenHelpers){const actual=sf.statements.find(s=>ts.isFunctionDeclaration(s)&&s.name?.text===frozen.name);assert.ok(actual);assert.equal(print(actual),frozen.body,'original helper '+frozen.name);}const m=manifest(),lane=m.lanes.find(l=>l.name==='profile');assert.deepEqual(lane.identities,profileFrozenTuples);assert.equal(lane.identities.length,6);assert.equal(m.lanes.flatMap(l=>l.identities).length,registeredIdentityCount());assert.throws(()=>assertEnvironment({PROFILE_E2E_OWNER_DIAGNOSTIC:'1'}));const config=readFileSync(resolve(process.cwd(),lane.config),'utf8');assert.equal(createHash('sha256').update(config).digest('hex'),"a342165aafa9b34d381cf77ef3a87975788761cc3bf567b96b968b2458b0e3a7");assert.match(config,/timeout: 90000/);assert.match(config,/timeout: 10000/);assert.match(config,/actionTimeout: 15000/);const protectedConfig=protectedBrowserConfiguration({use:{trace:'on',video:'on',screenshot:'on'},projects:[]},process.cwd(),lane.config,join(process.cwd(),'.synthetic-output'));assert.deepEqual([protectedConfig.use.trace,protectedConfig.use.video,protectedConfig.use.screenshot],['off','off','off']);});
test('Profile bounded diagnostic: exact synchronous stage placement all boundaries creation loop and one failure hook',async()=>{await profileHarness();const {ts,source,sf,print}=await profileAST(),target=profileTests(ts,sf).find(c=>c.arguments[0].text===profileTitle),body=target.arguments[1].body;assert.equal(target.arguments[1].parameters[1]?.name.getText(sf),'info');const direct=profileNativeBusinessBody(ts,sf,body).statements,creation=direct.find(s=>ts.isForOfStatement(s)&&s.getText(sf).includes('createNavigationList')),visibility=direct.find(s=>ts.isForOfStatement(s)&&s.getText(sf).includes('const control'));assert.ok(creation&&ts.isBlock(creation.statement),'creation loop must stage each category');assert.ok(visibility&&ts.isBlock(visibility.statement));const expectedDirect=[['none','setup','incomplete','incomplete'],['none','settings-open','incomplete','incomplete'],['none','visibility-open','incomplete','incomplete'],['none','legacy-check','incomplete','incomplete']],expectedIteration=[['category','control-enabled','incomplete','incomplete'],['category','initial-unchecked','incomplete','incomplete'],['category','publish-click','incomplete','incomplete'],['category','publish-poll','incomplete','incomplete'],['category','published-checked','completed','incomplete'],['category','hide-click','completed','incomplete'],['category','hide-poll','completed','incomplete'],['category','hidden-unchecked','completed','completed']];const values=s=>{const a=s.expression.arguments;assert.equal(a.length,5);assert.equal(a[0].getText(sf),'info');return a.slice(1).map(n=>ts.isStringLiteral(n)?n.text:n.getText(sf));};assert.deepEqual(direct.filter(s=>profileWrite(ts,sf,s)).map(values),expectedDirect);assert.deepEqual(creation.statement.statements.filter(s=>profileWrite(ts,sf,s)).map(values),[['category','collection-create','incomplete','incomplete']]);assert.deepEqual(visibility.statement.statements.filter(s=>profileWrite(ts,sf,s)).map(values),expectedIteration);assert.equal(creation.statement.statements.length,2);assert.ok(creation.statement.statements[1].getText(sf).includes('await createNavigationList(page, category)'));assert.ok(profileWrite(ts,sf,direct[0]));function before(statements,fragment,stage){const index=statements.findIndex(s=>!profileWrite(ts,sf,s)&&s.getText(sf).includes(fragment));assert.ok(index>0,'original boundary '+fragment);assert.ok(profileWrite(ts,sf,statements[index-1]),'immediate setter '+stage);assert.equal(values(statements[index-1])[1],stage);}for(const [fragment,stage] of [['await prepareNavigation(page)','setup'],['await openNavigation(page)','settings-open'],['name: /Public Visibility/i','visibility-open'],['expect(legacy).toEqual([])','legacy-check']])before(direct,fragment,stage);const iteration=visibility.statement.statements,operations=iteration.filter(s=>!profileWrite(ts,sf,s));assert.equal(operations.length,9);assert.ok(operations[0].getText(sf).includes('const control'));for(let i=1;i<operations.length;i++){const index=iteration.indexOf(operations[i]);assert.ok(profileWrite(ts,sf,iteration[index-1]));assert.deepEqual(values(iteration[index-1]),expectedIteration[i-1]);}const hooks=sf.statements.filter(s=>ts.isExpressionStatement(s)&&ts.isCallExpression(s.expression)&&s.expression.expression.getText(sf)==='test.afterEach');assert.equal(hooks.length,1);assert.equal(hooks[0].expression.arguments.length,1);const callback=hooks[0].expression.arguments[0];assert.ok(ts.isArrowFunction(callback)||ts.isFunctionExpression(callback));assert.equal(callback.parameters.length,2,'hook fixture and TestInfo parameters');assert.ok(ts.isObjectBindingPattern(callback.parameters[0].name)&&callback.parameters[0].name.elements.length===0,'hook has no fixture binding');assert.equal(callback.parameters[1].name.getText(sf),'info','hook second parameter TestInfo');assert.ok(callback.parameters.every(p=>!p.dotDotDotToken&&!p.questionToken&&!p.initializer));assert.ok(ts.isBlock(callback.body));assert.equal(callback.body.statements.length,4,'original captures and deferred diagnostic captures');assert.equal(print(callback.body.statements[3]),'captureSettingsReadiness(info);');assert.equal(print(callback.body.statements[2]),'captureProfileSecondSave(info);');assert.equal(print(callback.body.statements[1]),'nativeBoundaryObservers.get(info)?.finish(info);');const captureStatement=callback.body.statements[0];assert.ok(ts.isExpressionStatement(captureStatement)&&ts.isCallExpression(captureStatement.expression));assert.equal(print(captureStatement.expression),'captureProfileDiagnostic(info)');assert.ok(!callback.asteriskToken,'hook must execute immediately, never return a generator');assert.ok(!callback.modifiers?.some(m=>m.kind===ts.SyntaxKind.AsyncKeyword),'hook synchronous');const hookCalls=[];function inspect(n){assert.ok(!ts.isAwaitExpression(n),'diagnostic cannot await');if(ts.isCallExpression(n))hookCalls.push(n);ts.forEachChild(n,inspect);}inspect(callback.body.statements[0]);assert.deepEqual(hookCalls.map(c=>print(c)),['captureProfileDiagnostic(info)']);const start=source.indexOf('// BEGIN PROFILE DIAGNOSTIC CONTRACT'),end=source.indexOf('// END PROFILE DIAGNOSTIC CONTRACT'),block=ts.createSourceFile('contract.ts',source.slice(start,end),99,true);function guard(n){assert.ok(!ts.isAwaitExpression(n));assert.ok(!n.modifiers?.some(m=>m.kind===ts.SyntaxKind.AsyncKeyword));if(ts.isCallExpression(n))assert.doesNotMatch(n.expression.getText(block),/evaluate|request|fetch|setTimeout|setInterval|waitFor|\.on$|addEventListener|\.step$|retry|timeout/i);ts.forEachChild(n,guard);}guard(block);assert.doesNotMatch(source.slice(start,end)+hooks[0].getText(sf),/\bPage\b|\bPromise\b|\bdocument\b|\bwindow\b/);});

const profileFrozenHelpers=[{"name":"signInAs","body":"async function signInAs(page: Page, persona: Persona) {\n    const separator = persona.cookie.indexOf('=');\n    await page.context().addCookies([{ name: persona.cookie.slice(0, separator),\n            value: persona.cookie.slice(separator + 1), url: fixture.origin, sameSite: 'Lax' }]);\n    await page.addInitScript(({ userId, handle }) => {\n        localStorage.setItem('auth-storage', JSON.stringify({ state: {\n                isAuthenticated: true, token: 'profile-fixture-placeholder',\n                user: { id: userId, documentId: userId, username: handle,\n                    email: `${userId}@example.invalid`, blocked: false },\n            }, version: 0 }));\n    }, persona);\n    await page.route('**/*', (route) => {\n        const target = new URL(route.request().url());\n        if (target.protocol === 'data:' || target.protocol === 'blob:' || target.origin === fixture.origin)\n            return route.continue();\n        return route.abort();\n    });\n}"},{"name":"navigationAccount","body":"async function navigationAccount(page: Page): Promise<NavigationAccount> {\n    const response = await page.request.get(`${fixture.origin}${navigationBase}/me`);\n    expect(response.status()).toBe(200);\n    return (await response.json()).account;\n}"},{"name":"navigationPatch","body":"async function navigationPatch(page: Page, data: Record<string, unknown>) {\n    return page.request.patch(`${fixture.origin}${navigationBase}/account`, {\n        headers: { Origin: fixture.origin }, data,\n    });\n}"},{"name":"navigationSession","body":"async function navigationSession(page: Page, persona: Persona) {\n    const separator = persona.cookie.indexOf('=');\n    await page.context().addCookies([{ name: persona.cookie.slice(0, separator),\n            value: persona.cookie.slice(separator + 1), url: fixture.origin, sameSite: 'Lax' }]);\n    await page.route('**/*', route => {\n        const target = new URL(route.request().url());\n        return target.origin === fixture.origin || ['data:', 'blob:'].includes(target.protocol)\n            ? route.continue() : route.abort();\n    });\n    const session = await page.request.get(`${fixture.origin}/api/auth/get-session`);\n    expect(session.status()).toBe(200);\n    expect((await session.json()).user?.id === persona.userId).toBe(true);\n    let account = await navigationAccount(page);\n    expect(account.id === persona.userId).toBe(false);\n    expect(account.id).toMatch(/^[0-9a-f-]{36}$/);\n    if (account.onboardingStatus !== 'complete') {\n        const response = await navigationPatch(page, { expectedRevision: account.revision,\n            onboardingStatus: 'complete', handle: persona.handle, displayName: 'Navigation Fixture', accountType: 'Personal' });\n        expect(response.status()).toBe(200);\n        account = await navigationAccount(page);\n    }\n    return account;\n}"},{"name":"prepareNavigation","body":"async function prepareNavigation(page: Page) {\n    const account = await navigationSession(page, navigationOwner);\n    const response = await navigationPatch(page, { expectedRevision: account.revision, autoPinning: false,\n        categories: account.categories.map(row => ({ ...row, isPublic: false, pinnedOrder: null })) });\n    expect(response.status()).toBe(200);\n    const legacyOperations: string[] = [];\n    page.on('request', request => {\n        if (new URL(request.url()).pathname === '/graphql') {\n            const operation = request.postDataJSON()?.operationName;\n            if (['CategoryNavigationAccount', 'SettingsAccount', 'PublicCategoryListCounts', 'CheckPublishedLists'].includes(operation))\n                legacyOperations.push(operation);\n        }\n    });\n    return legacyOperations;\n}"},{"name":"openNavigation","body":"async function openNavigation(page: Page) {\n    await page.goto('/settings#public-navigation');\n    await expect(page.getByRole('checkbox', { name: 'Auto-pin navigation tabs', exact: true })).toBeEnabled();\n}"},{"name":"createNavigationList","body":"async function createNavigationList(page: Page, category: 'books' | 'movies' | 'games') {\n    const response = await page.request.post(`${fixture.origin}${navigationBase}/collections`, {\n        headers: { Origin: fixture.origin, 'Idempotency-Key': crypto.randomUUID() },\n        data: { category, title: `Navigation ${category}`, slug: `navigation-${crypto.randomUUID()}`,\n            visibility: 'public', publicationState: 'published' },\n    });\n    expect(response.status()).toBe(201);\n    const collection = (await response.json()).collection;\n    expect(collection).toMatchObject({ accountId: (await navigationAccount(page)).id,\n        category, visibility: 'public', publicationState: 'published' });\n    return collection as {\n        id: string;\n        revision: number;\n    };\n}"}];

