const moviesPublicTitle='anonymous category later list complete hero and modal preserve zero fields';
const moviesPublicFile='explorers-earth/e2e/replatform/movies.spec.ts';
const moviesPublicStages=['setup','category-navigation','category-request','category-status','category-json','list-count','hero-count','later-pin','list-navigation','list-continuation','modal-open','modal-note','modal-zero','modal-close','later-list-navigation','later-list-visible','page-legacy-check','contexts-create','pages-create','contexts-monitor','dual-navigation','left-visible','right-visible','left-cookie-empty','right-cookie-empty','switch-other','other-visible','prior-owner-absent','right-still-visible','switch-back','restored-visible','other-owner-absent','left-legacy-check','right-legacy-check','contexts-close','screenshot'];
const moviesPublicMarker=stage=>'[movies-public-diagnostic-v1:'+stage+']';
function moviesPublicFixture(){const f=moviesFixture();f.identity=f.lane.identities.find(i=>i.project==='movies-mobile'&&i.titlePath.at(-1)===moviesPublicTitle);f.index=f.lane.identities.indexOf(f.identity);f.c=child(f.lane);f.c.status=1;f.c.receipt.results[f.index].status='unexpected';f.c.receipt.results[f.index].attempts[0].status='failed';f.failure={...f.failure,results:f.c.receipt.results};f.report=rawReport(f.lane,true);f.result=f.report.suites[0].specs[f.index].tests[0].results[0]={status:'failed',retry:0,errors:[{message:moviesPublicMarker('setup')}]};return f;}
const moviesPublicDecode=f=>decodeProtectedFailureDiagnostics(f.report,f.lane,process.cwd());
const moviesPublicMetadata=f=>moviesPublicDecode(f).filter(d=>Object.hasOwn(d,'moviesPublic'));
function moviesPublicValidate(f,value,extra={}){return validateFailureRecord(f.lane,{...f.failure,diagnostics:[{identity:f.identity,kind:'error',matcher:'unknown',locations:[],moviesPublic:value,...extra}]},provenance,f.c);}
test('Movies public bounded diagnostic: all 36 independent stage decoder and validator roundtrips',()=>{for(const stage of moviesPublicStages){const f=moviesPublicFixture();f.result.errors[0].message=moviesPublicMarker(stage);assert.deepEqual(moviesPublicMetadata(f).map(d=>d.moviesPublic),[{version:1,stage}]);assert.doesNotThrow(()=>moviesPublicValidate(f,{version:1,stage}));}});
test('Movies public bounded diagnostic: canonical descriptors no accessor reads and null prototype acceptance',()=>{const f=moviesPublicFixture(),valid={version:1,stage:'setup'};assert.doesNotThrow(()=>moviesPublicValidate(f,valid));assert.doesNotThrow(()=>moviesPublicValidate(f,Object.assign(Object.create(null),valid)));let reads=0;for(const value of [null,[],{},false,1,'setup',{stage:'setup'},{version:1},{...valid,version:2},{...valid,stage:'unknown'},{...valid,extra:1},Object.assign(Object.create({}),valid),Object.defineProperty({...valid},'hidden',{value:1}),{...valid,[Symbol('extra')]:1},...['version','stage'].flatMap(key=>[1,'setup','invalid',null].map(value=>Object.defineProperty({...valid},key,{enumerable:true,get(){reads++;return value;}})))])assert.throws(()=>moviesPublicValidate(f,value));assert.equal(reads,0);for(const key of ['version','stage'])for(const value of [null,true,[],{},0,'secret'])assert.throws(()=>moviesPublicValidate(f,{...valid,[key]:value}));});
