function blCallbackInventory(ts,sf){const printer=ts.createPrinter({removeComments:true}),print=n=>printer.printNode(ts.EmitHint.Unspecified,n,sf);return sf.statements.filter(s=>ts.isExpressionStatement(s)&&ts.isCallExpression(s.expression)&&s.expression.expression.getText(sf)==='test').map(s=>{const c=s.expression,calls=[];function walk(n){if(ts.isCallExpression(n))calls.push(print(n));ts.forEachChild(n,walk);}walk(c.arguments[1].body);return {title:c.arguments[0].text,bodyHash:createHash('sha256').update(print(c.arguments[1].body)).digest('hex'),calls};});}

