 const handles=[];let count=0;
 function control(node){const add=node.addEventListener.bind(node),remove=node.removeEventListener.bind(node);node.addEventListener=(name,listener)=>{if(name==='change')count++;add(name,listener);};node.removeEventListener=(name,listener)=>{if(name==='change')count--;remove(name,listener);};return {elementHandle:async()=>{const input={disposed:0,evaluateHandle:async fn=>{const value=fn(node),observer={disposed:0,evaluate:async callback=>callback(value),dispose:async()=>observer.disposed++};handles.push(observer);return observer;},dispose:async()=>input.disposed++};handles.push(input);return input;}};}
 const node=document.querySelector('input'),c=control(node),keys=Object.getOwnPropertyNames(node),i={};
 await h.observeNativeInteraction(c,i,'games','publish','before');assert.equal(count,1);
 await h.observeNativeInteraction(c,i,'games','publish','after');assert.equal(count,0);assert.equal(retained.get(i).changeReceived,false);
 node.dispatchEvent(new dom.window.Event('change'));assert.equal(retained.get(i).changeReceived,false);
 await h.observeNativeInteraction(c,i,'games','publish','before');assert.equal(count,1);
 await h.observeNativeInteraction(c,i,'games','publish','before');assert.equal(count,1,'handoff removes earlier listener');
