test('Settings readiness: listener setup exception seals partial registrations without changing business failure',async()=>{const h=await settingsHarness(),listeners=new Map(),info=profileInfo({title:settingsTitle,titlePath:[settingsTitle]}),original=info.errors[0],page={on:(k,v)=>{listeners.set(k,v);if(k==='response')throw Error('private-setup');},off:k=>listeners.delete(k),evaluate:async()=>{throw Error('closed');}},o=h.observeSettingsReadiness(page,info);assert.equal(listeners.size,0);await o.finish(true);h.captureSettingsReadiness(info);assert.strictEqual(info.errors[0],original);const f=settingsFixture();f.result.errors=info.errors;assert.equal(settingsCards(f)[0].networkSample,'u');});
test('Settings readiness: hidden ancestor projection and ordinal closed first opener binding',async()=>{let parent={parentElement:null,hasAttribute:()=>true,getAttribute:()=>null},input={disabled:false,checked:false,parentElement:parent,hasAttribute:()=>false,getAttribute:()=>null},h=await settingsHarness({document:{querySelectorAll:()=>[input],querySelector:()=>null},window:{},location:{hash:'other'},getComputedStyle:()=>({display:'block',visibility:'visible'})}),info=profileInfo({title:settingsTitle,titlePath:[settingsTitle]}),listeners=new Map(),page={on:(k,v)=>listeners.set(k,v),off:k=>listeners.delete(k),evaluate:async fn=>fn()},o=h.observeSettingsReadiness(page,info);await o.finish(true);h.captureSettingsReadiness(info);const f=settingsFixture();f.result.errors=info.errors;assert.equal(settingsCards(f)[0].hidden,'1');assert.equal(settingsCards(f)[0].opener,'initial-open');const otherInfo=profileInfo({title:settingsTitle,titlePath:[settingsTitle]});await h.observeSettingsReadiness(page,otherInfo).finish(false);await h.observeSettingsReadiness(page,otherInfo).finish(true);h.captureSettingsReadiness(otherInfo);assert.equal(otherInfo.errors.length,1);assert.equal(listeners.size,0);});
test('Settings readiness: deferred retention deletes pending evidence on nonfailure frozen and missing original',async()=>{for(const mode of ['passed','frozen','missing']){const h=await settingsHarness(),info=profileInfo({title:settingsTitle,titlePath:[settingsTitle]}),page={on:()=>{},off:()=>{},evaluate:async()=>{throw Error('closed');}};await h.observeSettingsReadiness(page,info).finish(true);if(mode==='passed')info.status='passed';if(mode==='frozen')Object.freeze(info.errors);if(mode==='missing')info.errors=[];const before=info.errors.length;h.captureSettingsReadiness(info);assert.equal(info.errors.length,before);info.status='failed';info.errors=[{message:'runner original'}];h.captureSettingsReadiness(info);assert.equal(info.errors.length,1);}});
test('Settings readiness: registered 158 manifest identities remain exact committed inventory',()=>{const current=manifest(),prior=JSON.parse(execFileSync('git',['show','HEAD:explorers-earth/e2e/replatform/suite-manifest.json'],{encoding:'utf8',windowsHide:true}));assert.deepEqual(current,prior);assert.equal(current.lanes.reduce((sum,lane)=>sum+lane.identities.length,0),158);assert.equal(current.lanes.find(lane=>lane.name==='profile').identities.length,6);});
test('Apps Vite finite: strict marker and failed owned record persistence',async()=>{
 const {decodeAppsFixtureFailureLine:decode,retainAppsFixtureFailure:retain}=await import('./replatform-e2e.mjs');
 const line='Apps owned fixture failed: stage=vite; category=refusal; viteOrigin=closed-before-ready; viteChildCode=0; viteChildSignal=none; viteStdioClosed=true; viteAdvertised=false; viteHttpReady=false; viteProbeOutcome=none; viteStderr=module-not-found; viteStderrBytes=26; viteStderrOverflow=false';
 assert.equal(decode(line),line);const record={lane:'apps',status:1};assert.equal(retain(record,{status:1,stderr:'PRIVATE\n'+line+'\n'}),line);assert.equal(record.appsFixtureFailure.marker,line);assert.equal(record.appsFixtureFailure.stage,'vite');assert.deepEqual(record.appsFixtureFailure.vite,{origin:'closed-before-ready',childCode:0,childSignal:'none',stdioClosed:true,advertised:false,httpReady:false,probeOutcome:'none',stderr:'module-not-found',stderrBytes:26,stderrOverflow:false});assert.deepEqual(JSON.parse(JSON.stringify(record)).appsFixtureFailure,record.appsFixtureFailure);assert.equal(JSON.stringify(record).includes('PRIVATE'),false);
 for(const unsafe of [line+'; viteOrigin=launch',line.replace('viteChildCode=0','viteChildCode=-0'),line.replace('viteChildCode=0','viteChildCode=2147483648'),line.replace('module-not-found','PRIVATE'),line.replace('stage=vite','stage=execution'),line.replace('viteStderrBytes=26','viteStderrBytes=4097')])assert.equal(decode(unsafe),undefined);
 for(const [lane,status,stderr]of [['profile',1,line+'\n'],['apps',0,line+'\n'],['apps',1,line+'\n'+line+'\n'],['apps',1,line]]){const r={lane,status};assert.equal(retain(r,{status,stderr}),undefined);assert.equal(r.appsFixtureFailure,undefined);}
 let reads=0;for(const key of ['lane','status','stderr']){const r={lane:'apps',status:1},c={status:1,stderr:line+'\n'};Object.defineProperty(key==='lane'?r:c,key,{get(){reads++;throw Error('PRIVATE');}});assert.equal(retain(r,c),undefined);}assert.equal(reads,0);
 const foreign={lane:'apps',status:1,[Symbol('private')]:true};assert.equal(retain(foreign,{status:1,stderr:line+'\n'}),undefined);
 assert.equal(retain(new Proxy({},{getPrototypeOf(){throw Error('PRIVATE');}}),{status:1,stderr:line+'\n'}),undefined);
 assert.equal(retain(record,{status:1,stderr:line.replace('viteChildCode=0','viteChildCode=1')+'\n'}),undefined);assert.equal(record.appsFixtureFailure.vite.childCode,0);
 for(const bad of [line+' testcase=PRIVATE',line.replace('; viteChildCode=0',''),line.replace('; viteChildCode=0','; foreign=0; viteChildCode=0'),line.replace('viteStdioClosed=true','viteStdioClosed=false'),line.replace('viteHttpReady=false','viteHttpReady=true')])assert.equal(decode(bad),undefined);
});
